\echo '== 3. Values the sync needs that this database REJECTS (EMPTY = schema OK) =='
with used(tbl, col, val) as (values
('sap_api_configs','module','COMMON'),
('sap_api_configs','module','SD'),
('sap_api_configs','api_type','fetch'),
('sap_api_configs','auth_type','basic'),
('sap_api_configs','http_method','GET'),
('sap_api_configs','http_method','POST'),
('sap_api_configs','http_method','PUT'),
('sap_api_request_fields','source','column'),
('sap_api_request_fields','source','static'),
('role_permissions','action','approve'),
('role_permissions','action','create'),
('role_permissions','action','delete'),
('role_permissions','action','edit'),
('role_permissions','action','export'),
('role_permissions','action','view')
),
checks as (
  select cl.relname as tbl, pg_get_constraintdef(con.oid) as def
  from pg_constraint con
  join pg_class cl on cl.oid = con.conrelid
  join pg_namespace ns on ns.oid = cl.relnamespace
  where ns.nspname = 'public' and con.contype = 'c'
)
select u.tbl, u.col, u.val, ch.def as constraint_definition
from used u
join checks ch on ch.tbl = u.tbl and ch.def like '%(' || u.col || ' =%'
where position(quote_literal(u.val) in ch.def) = 0
order by 1, 2, 3;

