select e.name,
       e.req_count as expected_request_fields,
       (select count(*) from public.sap_api_request_fields r where r.config_id = c.id) as actual_request_fields,
       e.res_count as expected_response_fields,
       (select count(*) from public.sap_api_response_fields s where s.config_id = c.id) as actual_response_fields
from expected e
join public.sap_api_configs c on c.name = e.name
where (select count(*) from public.sap_api_request_fields r where r.config_id = c.id) <> e.req_count
   or (select count(*) from public.sap_api_response_fields s where s.config_id = c.id) <> e.res_count
order by 1;

